        let stream = self.__ctx.new_stream()?;
        for dep in after { dep.synchronize()?; }
        let mut launcher = stream.launch_builder(&func);
        launcher.arg(&self.alpha);
        launcher.arg(&mut self.x);
        launcher.arg(&mut self.y);
        unsafe { launcher.launch(cfg) }?;
        let stream = Arc::new(stream);
        Ok(KernelHandle { inner: self, stream })
