fn main() -> Result<(), Box<dyn std::error::Error>> {
    boring_gpu_init()?;
    let N = 16;
    let alpha = 2.0;
    let g = boring_gpu_ctx_n(0 as usize)?;
    println!("Device : {}", g.name()?);
    println!("Memory : {} GB", (g.total_mem()? / 1073741824));
    let mut x: Vec<f64> = vec![0.0; N as usize];
    let mut y: Vec<f64> = vec![1.0; N as usize];
    for i in 0..N {
        x[i as usize] = (i as f64);
    }
    let mut k = Saxpy::new(boring_gpu_ctx(), alpha, x, y)?;
    let mut k = k.__boring_launch((N as u32, 1, 1), None, &[])?.wait()?;
    println!("{}", "Results (expected: y[i] = 2*i + 1):");
    for (i, v) in k.read_y()?.iter().enumerate() {
        println!("  y[{}] = {}", i, v);
    }
    Ok(())
}
